type ModuleId = 'rw1' | 'rw2' | 'math1' | 'math2'
type Visual = { asset: string; alt: string }

export type OctoberQuestion = {
  id: string
  moduleId: ModuleId
  number: number
  prompt: string
  kind: 'multiple-choice' | 'student-response'
  correctAnswer: string
  acceptedAnswers?: string[]
  tolerance?: number
  choices: Array<{ key: string; text: string }>
  visual?: Visual
  rationale: string
}

const keys = ['A', 'B', 'C', 'D']

function mc(moduleId: ModuleId, number: number, prompt: string, correctAnswer: string, choices: string[], rationale: string, visual?: Visual): OctoberQuestion {
  return { id: `${moduleId}-${number}`, moduleId, number, prompt, kind: 'multiple-choice', correctAnswer, choices: choices.map((text, index) => ({ key: keys[index], text })), rationale, visual }
}

function sr(moduleId: ModuleId, number: number, prompt: string, acceptedAnswers: string[], rationale: string, tolerance?: number, visual?: Visual): OctoberQuestion {
  return { id: `${moduleId}-${number}`, moduleId, number, prompt, kind: 'student-response', correctAnswer: acceptedAnswers[0], acceptedAnswers, tolerance, choices: [], rationale, visual }
}

